from collections import defaultdict, deque

def topological_sort(graph):
    node_count = len(graph)
    visited = [False] * node_count
    stack = []

    # Using DFS to check for cycles
    def dfs(node):
        visited[node] = True
        for neighbor in graph.get(node, []):
            if not visited[neighbor]:
                if not dfs(neighbor):
                    return False
